PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS owner_state(owner_id TEXT PRIMARY KEY, spend_blocked INTEGER NOT NULL DEFAULT 0 CHECK(spend_blocked IN(0,1)), reasons TEXT NOT NULL DEFAULT '[]', session_generation INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE IF NOT EXISTS mandates(id TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES owner_state(owner_id),version INTEGER NOT NULL CHECK(version>0),status TEXT NOT NULL CHECK(status IN('ACTIVE','REVOKED','EXPIRED','SUPERSEDED')),policy_json TEXT NOT NULL,content_hash TEXT NOT NULL,signed_at TEXT NOT NULL,revoked_at INTEGER,PRIMARY KEY(id,version)) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS active_owner ON mandates(owner_id) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS budget_buckets(owner_id TEXT NOT NULL REFERENCES owner_state(owner_id),period_key TEXT NOT NULL,allowance INTEGER NOT NULL CHECK(allowance BETWEEN 1 AND 50000),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved BETWEEN 0 AND 1000000000000),captured INTEGER NOT NULL DEFAULT 0 CHECK(captured BETWEEN 0 AND 1000000000000),refunded_completed INTEGER NOT NULL DEFAULT 0 CHECK(refunded_completed BETWEEN 0 AND 1000000000000),restored INTEGER NOT NULL DEFAULT 0 CHECK(restored BETWEEN 0 AND refunded_completed),external_refunded INTEGER NOT NULL DEFAULT 0 CHECK(external_refunded BETWEEN 0 AND 1000000000000),PRIMARY KEY(owner_id,period_key)) STRICT;
CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,mandate_id TEXT NOT NULL,policy_version INTEGER NOT NULL,policy_hash TEXT NOT NULL,period_key TEXT NOT NULL,restoration TEXT NOT NULL CHECK(restoration IN('never_restore','restore_on_completed_refund')),state TEXT NOT NULL CHECK(state IN('HELD','CREATING','CREATE_UNKNOWN','ORDER_CREATED','APPROVED','CAPTURING','CAPTURE_PROVIDER_PENDING','CAPTURE_UNKNOWN','CAPTURED','RELEASED')),amount INTEGER NOT NULL CHECK(amount BETWEEN 1 AND 50000),hold_minor INTEGER NOT NULL CHECK(hold_minor IN(0,amount)),captured_minor INTEGER NOT NULL DEFAULT 0 CHECK(captured_minor BETWEEN 0 AND 1000000000000),external_refunded_minor INTEGER NOT NULL DEFAULT 0 CHECK(external_refunded_minor BETWEEN 0 AND 1000000000000),order_id TEXT UNIQUE,anomaly_open INTEGER NOT NULL DEFAULT 0 CHECK(anomaly_open IN(0,1)),anomaly_reasons TEXT NOT NULL DEFAULT '[]',release_on_resolve INTEGER NOT NULL DEFAULT 0 CHECK(release_on_resolve IN(0,1)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(owner_id,period_key) REFERENCES budget_buckets(owner_id,period_key),FOREIGN KEY(mandate_id,policy_version) REFERENCES mandates(id,version)) STRICT;
CREATE TABLE IF NOT EXISTS reservation_lines(reservation_id TEXT NOT NULL REFERENCES reservations(id),sku TEXT NOT NULL,category_id TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty BETWEEN 1 AND 20),unit_minor INTEGER NOT NULL CHECK(unit_minor BETWEEN 0 AND 1000000000000),line_minor INTEGER NOT NULL CHECK(line_minor BETWEEN 0 AND 1000000000000),PRIMARY KEY(reservation_id,sku)) STRICT;
CREATE TABLE IF NOT EXISTS provider_captures(capture_id TEXT PRIMARY KEY,reservation_id TEXT NOT NULL REFERENCES reservations(id),order_id TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency='USD'),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 1000000000000),completion_observed INTEGER NOT NULL CHECK(completion_observed=1),raw_fact_hash TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,capture_id TEXT NOT NULL REFERENCES provider_captures(capture_id),reservation_id TEXT NOT NULL REFERENCES reservations(id),amount INTEGER NOT NULL CHECK(amount BETWEEN 1 AND 1000000000000),state TEXT NOT NULL CHECK(state IN('REQUESTED','SUBMITTING','PROVIDER_PENDING','REFUND_UNKNOWN','COMPLETED','FAILED','CANCELLED')),completed_applied INTEGER NOT NULL DEFAULT 0 CHECK(completed_applied IN(0,1)),provider_refund_id TEXT UNIQUE,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,CHECK(completed_applied=0 OR state='COMPLETED')) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS one_active_refund ON refunds(capture_id) WHERE state IN('REQUESTED','SUBMITTING','PROVIDER_PENDING','REFUND_UNKNOWN');
CREATE TABLE IF NOT EXISTS provider_refund_facts(refund_id TEXT PRIMARY KEY,capture_id TEXT NOT NULL REFERENCES provider_captures(capture_id),currency TEXT NOT NULL CHECK(currency='USD'),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 1000000000000),completion_observed INTEGER NOT NULL CHECK(completion_observed=1),local_refund_id TEXT UNIQUE REFERENCES refunds(id),raw_fact_hash TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS provider_observations(seq INTEGER PRIMARY KEY AUTOINCREMENT,resource_id TEXT NOT NULL,payload_hash TEXT NOT NULL,bounded_redacted_json TEXT NOT NULL CHECK(length(CAST(bounded_redacted_json AS BLOB))<=16384),source TEXT NOT NULL CHECK(source IN('fixture','sandbox')),observed_at INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('ORDER_CREATE','ORDER_CAPTURE','REFUND_CREATE')),subject_id TEXT NOT NULL,request_id TEXT NOT NULL UNIQUE CHECK(length(request_id)=36 AND substr(request_id,15,1)='4' AND substr(request_id,20,1) IN('8','9','a','b') AND substr(request_id,9,1)='-' AND substr(request_id,14,1)='-' AND substr(request_id,19,1)='-' AND substr(request_id,24,1)='-' AND length(replace(request_id,'-',''))=32 AND replace(request_id,'-','') NOT GLOB '*[^0-9a-f]*'),canonical_body TEXT NOT NULL,body_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('READY','SENDING','DONE','FAILED_DEFINITIVE','UNKNOWN','MANUAL')),attempt INTEGER NOT NULL DEFAULT 0 CHECK(attempt IN(0,1)),owner_token TEXT,claimed_at INTEGER,send_deadline INTEGER,first_attempt_at INTEGER,horizon_until INTEGER,next_get_at INTEGER,get_attempts INTEGER NOT NULL DEFAULT 0 CHECK(get_attempts BETWEEN 0 AND 24),last_get_at INTEGER,last_error TEXT,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(kind,subject_id),CHECK((state='READY' AND attempt=0) OR state!='READY'),CHECK(attempt=0 OR (claimed_at IS NOT NULL AND send_deadline IS NOT NULL AND horizon_until IS NOT NULL AND owner_token IS NOT NULL))) STRICT;
CREATE TRIGGER IF NOT EXISTS operation_no_retry BEFORE UPDATE ON operations WHEN NEW.attempt<OLD.attempt OR (OLD.state!='READY' AND NEW.state='READY') OR (OLD.attempt=1 AND (NEW.owner_token IS NOT OLD.owner_token OR NEW.claimed_at IS NOT OLD.claimed_at OR NEW.send_deadline IS NOT OLD.send_deadline OR NEW.horizon_until IS NOT OLD.horizon_until)) OR NEW.get_attempts<OLD.get_attempts BEGIN SELECT RAISE(ABORT,'OPERATION_NO_POST_TAKEOVER'); END;
CREATE TRIGGER IF NOT EXISTS operation_body_immutable BEFORE UPDATE ON operations WHEN NEW.kind!=OLD.kind OR NEW.subject_id!=OLD.subject_id OR NEW.request_id!=OLD.request_id OR NEW.canonical_body!=OLD.canonical_body OR NEW.body_hash!=OLD.body_hash OR NEW.expires_at!=OLD.expires_at BEGIN SELECT RAISE(ABORT,'OPERATION_IMMUTABLE'); END;
CREATE TABLE IF NOT EXISTS idempotency_keys(scope TEXT NOT NULL,key TEXT NOT NULL,body_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('IN_PROGRESS','COMPLETE','TOMBSTONE')),owner_token TEXT,lease_until INTEGER,response_json TEXT,response_status INTEGER,effect_id TEXT,created_at INTEGER NOT NULL,completed_at INTEGER,PRIMARY KEY(scope,key)) STRICT;
CREATE TRIGGER IF NOT EXISTS tombstone_permanent BEFORE DELETE ON idempotency_keys BEGIN SELECT RAISE(ABORT,'IDEMPOTENCY_IDENTITY_PERMANENT'); END;
CREATE TRIGGER IF NOT EXISTS idempotency_no_reexecute BEFORE UPDATE ON idempotency_keys WHEN NEW.scope!=OLD.scope OR NEW.key!=OLD.key OR NEW.body_hash!=OLD.body_hash OR (OLD.state IN('COMPLETE','TOMBSTONE') AND NEW.state='IN_PROGRESS') OR (OLD.state='TOMBSTONE' AND NEW.state!='TOMBSTONE') BEGIN SELECT RAISE(ABORT,'IDEMPOTENCY_IMMUTABLE'); END;
CREATE TABLE IF NOT EXISTS webhook_deliveries(seq INTEGER PRIMARY KEY AUTOINCREMENT,event_id TEXT,transmission_id TEXT,received_at INTEGER NOT NULL,verification_state TEXT NOT NULL CHECK(verification_state IN('UNVERIFIED','INVALID','VERIFIED')),verify_reason TEXT,body_hash TEXT NOT NULL,raw_body BLOB,allowlisted_headers TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS webhook_events(event_id TEXT PRIMARY KEY,verified_delivery_seq INTEGER NOT NULL REFERENCES webhook_deliveries(seq),body_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('PENDING','COMPLETE','CONFLICT')),resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,created_at INTEGER NOT NULL) STRICT;
CREATE TRIGGER IF NOT EXISTS verified_only BEFORE INSERT ON webhook_events WHEN NOT EXISTS(SELECT 1 FROM webhook_deliveries WHERE seq=NEW.verified_delivery_seq AND verification_state='VERIFIED' AND event_id=NEW.event_id AND body_hash=NEW.body_hash) BEGIN SELECT RAISE(ABORT,'VERIFIED_DELIVERY_REQUIRED'); END;
CREATE TABLE IF NOT EXISTS reconcile_jobs(subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('PENDING','ACTIVE','COMPLETE','MANUAL')),owner_token TEXT,lease_until INTEGER,attempts INTEGER NOT NULL DEFAULT 0,deadline INTEGER NOT NULL,next_at INTEGER NOT NULL,PRIMARY KEY(subject_type,subject_id)) STRICT;
CREATE TABLE IF NOT EXISTS maintenance_lock(name TEXT PRIMARY KEY,owner_token TEXT,lease_until INTEGER,cursor TEXT NOT NULL DEFAULT '',last_clock INTEGER) STRICT;
CREATE TABLE IF NOT EXISTS ledger_rows(seq INTEGER PRIMARY KEY AUTOINCREMENT,at INTEGER NOT NULL,owner_id TEXT NOT NULL,mandate_id TEXT NOT NULL,policy_version INTEGER NOT NULL,period_key TEXT NOT NULL,kind TEXT NOT NULL,reservation_id TEXT,amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN -1000000000000 AND 1000000000000),available_after INTEGER NOT NULL,reserved_after INTEGER NOT NULL,captured_after INTEGER NOT NULL,restored_after INTEGER NOT NULL,refunded_completed_after INTEGER NOT NULL,rule_ids TEXT NOT NULL DEFAULT '[]',paypal TEXT NOT NULL DEFAULT '{}',source TEXT NOT NULL CHECK(source IN('fixture','sandbox')),note TEXT NOT NULL) STRICT;
CREATE TRIGGER IF NOT EXISTS ledger_no_update BEFORE UPDATE ON ledger_rows BEGIN SELECT RAISE(ABORT,'AUDIT_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ledger_no_delete BEFORE DELETE ON ledger_rows BEGIN SELECT RAISE(ABORT,'AUDIT_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS bucket_insert_guard BEFORE INSERT ON budget_buckets WHEN NEW.reserved>0 AND (NEW.allowance-NEW.reserved-NEW.captured+NEW.restored<0 OR EXISTS(SELECT 1 FROM owner_state WHERE owner_id=NEW.owner_id AND spend_blocked=1)) BEGIN SELECT RAISE(ABORT,'BUDGET_SPEND_GUARD'); END;
CREATE TRIGGER IF NOT EXISTS bucket_update_guard BEFORE UPDATE ON budget_buckets WHEN ((NEW.reserved>OLD.reserved OR NEW.allowance<OLD.allowance) AND NEW.allowance-NEW.reserved-NEW.captured+NEW.restored<0) OR (NEW.reserved>OLD.reserved AND EXISTS(SELECT 1 FROM owner_state WHERE owner_id=NEW.owner_id AND spend_blocked=1)) BEGIN SELECT RAISE(ABORT,'BUDGET_SPEND_GUARD'); END;
CREATE TRIGGER IF NOT EXISTS reservation_hold_insert BEFORE INSERT ON reservations WHEN NEW.hold_minor>0 AND (EXISTS(SELECT 1 FROM owner_state WHERE owner_id=NEW.owner_id AND spend_blocked=1) OR NOT EXISTS(SELECT 1 FROM budget_buckets WHERE owner_id=NEW.owner_id AND period_key=NEW.period_key AND reserved >= COALESCE((SELECT SUM(hold_minor) FROM reservations WHERE owner_id=NEW.owner_id AND period_key=NEW.period_key),0)+NEW.hold_minor)) BEGIN SELECT RAISE(ABORT,'HOLD_SPEND_GUARD'); END;
CREATE TRIGGER IF NOT EXISTS reservation_hold_update BEFORE UPDATE ON reservations WHEN NEW.hold_minor>OLD.hold_minor AND (OLD.hold_minor=0 OR EXISTS(SELECT 1 FROM owner_state WHERE owner_id=NEW.owner_id AND spend_blocked=1) OR NOT EXISTS(SELECT 1 FROM budget_buckets WHERE owner_id=NEW.owner_id AND period_key=NEW.period_key AND reserved >= COALESCE((SELECT SUM(hold_minor) FROM reservations WHERE owner_id=NEW.owner_id AND period_key=NEW.period_key),0)+NEW.hold_minor-OLD.hold_minor)) BEGIN SELECT RAISE(ABORT,'HOLD_SPEND_GUARD'); END;
CREATE TRIGGER IF NOT EXISTS reservation_snapshot BEFORE UPDATE ON reservations WHEN NEW.owner_id!=OLD.owner_id OR NEW.mandate_id!=OLD.mandate_id OR NEW.policy_version!=OLD.policy_version OR NEW.policy_hash!=OLD.policy_hash OR NEW.period_key!=OLD.period_key OR NEW.restoration!=OLD.restoration OR NEW.amount!=OLD.amount BEGIN SELECT RAISE(ABORT,'RESERVATION_SNAPSHOT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS line_snapshot_update BEFORE UPDATE ON reservation_lines BEGIN SELECT RAISE(ABORT,'LINE_SNAPSHOT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS line_snapshot_delete BEFORE DELETE ON reservation_lines BEGIN SELECT RAISE(ABORT,'LINE_SNAPSHOT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS refund_cas_monotone BEFORE UPDATE ON refunds WHEN NEW.completed_applied<OLD.completed_applied OR NEW.amount!=OLD.amount OR NEW.capture_id!=OLD.capture_id OR NEW.reservation_id!=OLD.reservation_id BEGIN SELECT RAISE(ABORT,'REFUND_FACT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS capture_fact_immutable BEFORE UPDATE ON provider_captures BEGIN SELECT RAISE(ABORT,'CAPTURE_FACT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS capture_fact_retained BEFORE DELETE ON provider_captures BEGIN SELECT RAISE(ABORT,'CAPTURE_FACT_RETAINED'); END;
CREATE TRIGGER IF NOT EXISTS refund_fact_retained BEFORE DELETE ON provider_refund_facts BEGIN SELECT RAISE(ABORT,'REFUND_FACT_RETAINED'); END;
CREATE TABLE IF NOT EXISTS capture_status_facts(capture_id TEXT NOT NULL,reservation_id TEXT NOT NULL REFERENCES reservations(id),status TEXT NOT NULL CHECK(status IN('PENDING','DECLINED')),PRIMARY KEY(capture_id,status)) STRICT;
CREATE TRIGGER IF NOT EXISTS refund_fact_identity BEFORE UPDATE ON provider_refund_facts WHEN NEW.refund_id!=OLD.refund_id OR NEW.capture_id!=OLD.capture_id OR NEW.currency!=OLD.currency OR NEW.amount_minor!=OLD.amount_minor OR NEW.completion_observed!=OLD.completion_observed OR (OLD.local_refund_id IS NOT NULL AND NEW.local_refund_id IS NOT OLD.local_refund_id) BEGIN SELECT RAISE(ABORT,'REFUND_FACT_IMMUTABLE'); END;
CREATE TRIGGER IF NOT EXISTS operation_identity_retained BEFORE DELETE ON operations BEGIN SELECT RAISE(ABORT,'OPERATION_IDENTITY_RETAINED'); END;
